/**
 * The kitchen's audible new-order alert.
 *
 * A cook is at the pass with their hands full, not watching a tablet. The
 * banner and the haptic in `newKotAlerts` both assume someone is looking at or
 * holding the device, which in a kitchen is the one thing you cannot assume —
 * so sound is the primary channel here and the other two are the backup.
 *
 * The asset is generated by `scripts/generateChime.js` (see that file for why
 * it sounds the way it does). Regenerate it there rather than swapping in a
 * downloaded clip, so the chime stays something a diff can explain.
 *
 * ## The load-bearing decisions
 *
 * - **`expo-audio` is a NATIVE module, so this only works in an APK built
 *   after it landed.** Every entry point is wrapped: an older install (or Expo
 *   Go on an SDK without it) silently gets no sound and keeps the banner and
 *   the haptic, exactly the way `printerService` degrades to Bluetooth-only.
 *   A kitchen screen must never white-screen because it couldn't beep.
 * - **One player, created once, rewound per play.** Constructing a player per
 *   chime leaks native decoders and adds a load delay in front of an alert
 *   whose entire job is to be immediate.
 * - **`playsInSilentMode`.** A kitchen tablet lives face-down on a steel bench
 *   and gets muted by accident constantly. This is the one sound in the app,
 *   it only fires on a real order, and an unheard order is a walkout — so it
 *   opts out of the silent switch. It still respects the volume slider.
 */
import { Platform } from "react-native";

/** Resolved lazily; `null` once we know the native module isn't there. */
let player: { seekTo: (s: number) => Promise<void>; play: () => void } | null =
  null;
let initialised = false;
let available = true;

/**
 * `require` rather than a static import: a static one is hoisted and evaluated
 * when this module is first touched, which on a build without the native side
 * throws during import — before any try/catch of ours can run.
 */
function init(): void {
  if (initialised) return;
  initialised = true;
  try {
    const audio = require("expo-audio");
    // Fire-and-forget: the mode only affects how the OS routes the sound, so a
    // failure here should not stop us creating the player.
    audio
      .setAudioModeAsync({
        // On Android `false` here suppresses playback whenever the ringer is
        // silent or on vibrate, which is where a bench tablet spends its life.
        playsInSilentMode: true,
        shouldPlayInBackground: false,
        // Don't stop the manager's music or a timer app for a 1s chime.
        interruptionMode: "mixWithOthers",
      })
      ?.catch?.(() => {});
    player = audio.createAudioPlayer(
      require("../../assets/sounds/new-order.wav")
    );
  } catch {
    available = false;
    player = null;
  }
}

/**
 * Play the chime once, from the top.
 *
 * Safe to call while it is already sounding — the rewind means two orders
 * landing together produce one clean chime rather than a doubled, phasing one.
 */
export function playNewOrderChime(): void {
  if (Platform.OS === "web") return;
  init();
  if (!player) return;
  const p = player;
  try {
    // `seekTo` is async, so play() has to wait for it — firing them together
    // resumes from wherever the previous chime stopped, which on the second
    // play is the very end and therefore silence.
    p.seekTo(0)
      .then(() => p.play())
      // A decoder that dies mid-service must not take the board down with it.
      .catch(() => {});
  } catch {
    // seekTo can also throw synchronously if the native side has gone away.
  }
}

/**
 * Whether the running build can actually make a sound. The KDS uses this to
 * tell the kitchen that sound is unavailable, rather than leaving them to
 * trust an alert that will never come.
 */
export function isChimeAvailable(): boolean {
  init();
  return available && player != null;
}
